    "<svg viewBox=\"0 0 240 52\" width=\"240\" role=\"img\" aria-label=\"Sayı doğrusu: 2520 &lt; x ≤ 2950; 3050 ≤ x &lt; 3480\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"14\" y1=\"18\" x2=\"226\" y2=\"18\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><polygon points=\"4,18 16,12 16,24\" fill=\"#1e293b\"/><polygon points=\"236,18 224,12 224,24\" fill=\"#1e293b\"/><line x1=\"40\" y1=\"18\" x2=\"92\" y2=\"18\" stroke=\"#2563eb\" stroke-width=\"5\"/><line x1=\"148\" y1=\"18\" x2=\"200\" y2=\"18\" stroke=\"#2563eb\" stroke-width=\"5\"/><circle cx=\"40\" cy=\"18\" r=\"6\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><circle cx=\"92\" cy=\"18\" r=\"6\" fill=\"#2563eb\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><circle cx=\"148\" cy=\"18\" r=\"6\" fill=\"#2563eb\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><circle cx=\"200\" cy=\"18\" r=\"6\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><text x=\"40\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">2520</text><text x=\"92\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">2950</text><text x=\"148\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">3050</text><text x=\"200\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">3480</text></svg>"
