    "<svg viewBox=\"0 0 240 52\" width=\"240\" role=\"img\" aria-label=\"Sayı doğrusu: 28 &lt; x &lt; 40\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"14\" y1=\"18\" x2=\"226\" y2=\"18\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><polygon points=\"4,18 16,12 16,24\" fill=\"#1e293b\"/><polygon points=\"236,18 224,12 224,24\" fill=\"#1e293b\"/><line x1=\"75\" y1=\"18\" x2=\"165\" y2=\"18\" stroke=\"#2563eb\" stroke-width=\"5\"/><circle cx=\"75\" cy=\"18\" r=\"6\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><circle cx=\"165\" cy=\"18\" r=\"6\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><text x=\"75\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">28</text><text x=\"165\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">40</text></svg>",
    "<svg viewBox=\"0 0 240 52\" width=\"240\" role=\"img\" aria-label=\"Sayı doğrusu: 28 ≤ x ≤ 30\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"14\" y1=\"18\" x2=\"226\" y2=\"18\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><polygon points=\"4,18 16,12 16,24\" fill=\"#1e293b\"/><polygon points=\"236,18 224,12 224,24\" fill=\"#1e293b\"/><line x1=\"75\" y1=\"18\" x2=\"165\" y2=\"18\" stroke=\"#2563eb\" stroke-width=\"5\"/><circle cx=\"75\" cy=\"18\" r=\"6\" fill=\"#2563eb\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><circle cx=\"165\" cy=\"18\" r=\"6\" fill=\"#2563eb\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><text x=\"75\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">28</text><text x=\"165\" y=\"44\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e293b\">30</text></svg>"
